W, Ht = A4; mx = 15*mm; gap = 6*mm; cw = (W - 2*mx - gap) / 2; top = 18*mm; bot = 14*mm
def img(p, w=None):
    a, b = PI.open(p).size; w = w or cw; return Image(p, w, w * b / a)
def fig(p, cap, w=None): return KeepTogether([img(p, w), P(cap, CAP)])
def tbl(data, cws, cap, bold_row=None, align_left_first=True):
    rows = [[Paragraph(str(c), ParagraphStyle("c", fontName="Sans-B" if i == 0 else "Sans", fontSize=6.3, leading=7.4, alignment=0 if j == 0 and align_left_first else 1)) for j, c in enumerate(r)] for i, r in enumerate(data)]
    t = Table(rows, colWidths=[c * cw for c in cws], repeatRows=1)
    sty = [("LINEABOVE", (0, 0), (-1, 0), .9, colors.black), ("LINEBELOW", (0, 0), (-1, 0), .5, colors.black), ("LINEBELOW", (0, -1), (-1, -1), .9, colors.black),
           ("TOPPADDING", (0, 0), (-1, -1), 1.3), ("BOTTOMPADDING", (0, 0), (-1, -1), 1.3), ("LEFTPADDING", (0, 0), (-1, -1), 2), ("RIGHTPADDING", (0, 0), (-1, -1), 2), ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#efe9f1"))]
    if bold_row is not None: sty.append(("BACKGROUND", (0, bold_row), (-1, bold_row), colors.HexColor("#f6f1d8")))
    t.setStyle(TableStyle(sty)); return KeepTogether([P(cap, TC), t, Spacer(1, 5)])

